"""Saved-output-only retrospective research report; never imports training entrypoints."""
import csv,html,json,hashlib
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from sklearn.metrics import balanced_accuracy_score,classification_report,confusion_matrix
ROOT=Path(__file__).resolve().parents[2]
FEATURE=ROOT/'artifacts/feature-benchmark/4514bab7aa7e4dba837581882bfe6be4'
CALIBRATION=ROOT/'artifacts/calibration-development/6677c8dddba2493f8149ee31e60b57ec'
def paired(rows,group,reference,budget=None):
 def scores(method):
  selected=[r for r in rows if group(r)==method and (budget is None or r['budget']==budget)]
  return {s:float(np.mean([r['score'] for r in selected if r['subject']==s])) for s in sorted({r['subject'] for r in selected})}
 a,b=scores(reference[0]),scores(reference[1]);subjects=sorted(a.keys()&b.keys())
 if not subjects:raise ValueError('No matched participants')
 d=np.array([a[s]-b[s] for s in subjects]);rng=np.random.default_rng(712);ci=np.quantile(rng.choice(d,(10000,len(d)),replace=True).mean(1),[.025,.975])
 return dict(comparison=reference,budget=budget,participants=subjects,differences=d.tolist(),mean=float(d.mean()),bootstrap95=ci.tolist())
def enrich(rows,feature=False):
 result=[]
 for row in rows:
  r=dict(row);p=np.array(r['probabilities']);y=np.array(r['labels']);pred=p.argmax(1);r.update(score=float(balanced_accuracy_score(y,pred)),classification=classification_report(y,pred,output_dict=True,zero_division=0),confusion=confusion_matrix(y,pred,labels=[0,1]).tolist(),predicted_counts=np.bincount(pred,minlength=2).tolist(),trials=len(y),group=(r['representation']+' '+r['method']) if feature else r['method'])
  if not feature:r['coverage']=float(np.mean(r['quality']))
  result.append(r)
 return result
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def main():
 out=ROOT/'artifacts/consolidated-report';out.mkdir(exist_ok=True);f=enrich(json.loads((FEATURE/'results.json').read_text()),True);c=enrich(json.loads((CALIBRATION/'results.json').read_text()));verification=json.loads((FEATURE/'verification-complete.json').read_text());groups=sorted({r['group'] for r in f});subjects=sorted({r['subject'] for r in f});methods=['frozen','fine_tuned','subject_specific','csp_lda'];budgets=[4,8,12]
 comparisons=[('bandpower neural','bandpower lda'),('csp neural','csp lda'),('bandpower neural','time neural'),('csp neural','time neural'),('bandpower lda','time neural')]
 result=dict(feature=[paired(f,lambda r:r['group'],p) for p in comparisons],calibration=[paired(c,lambda r:r['group'],('fine_tuned',m),b) for b in budgets for m in ['frozen','subject_specific','csp_lda']]);(out/'paired.json').write_text(json.dumps(result,indent=2));(out/'classification-details.json').write_text(json.dumps(dict(feature=f,calibration=c),indent=2))
 def mean(rows,key):return float(np.mean([r[key] for r in rows]))
 fig,ax=plt.subplots(2,2,figsize=(14,10))
 for i,g in enumerate(groups):
  rr=[r for r in f if r['group']==g];values=[mean([r for r in rr if r['subject']==s],'score') for s in subjects]
  ax[0,0].scatter([i]*len(values),values,label=g);ax[0,0].plot(i,np.mean(values),'kx');ax[0,1].scatter([i]*len(rr),[r['score'] for r in rr],s=18)
  for label,offset in [('0',-.15),('1',.15)]:ax[1,0].bar(i+offset,np.mean([r['classification'][label]['recall'] for r in rr]),width=.28,color=('#1f77b4' if label=='0' else '#ff7f0e'),label=('Left' if label=='0' else 'Right') if i==0 else None)
 for axis in [ax[0,0],ax[0,1],ax[1,0]]:axis.set_xticks(range(len(groups)),groups,rotation=25,ha='right');axis.set_ylim(0,1);axis.axhline(.5,ls=':',color='gray')
 ax[0,0].set_title('Participant means (seeds averaged); crosses = mean');ax[0,1].set_title('Every neural seed / statistical configuration');ax[1,0].set_title('Class recall, all evaluation trials');ax[1,0].legend()
 ax[1,1].bar(list(map(str,subjects)),[next(r['coverage'] for r in f if r['subject']==s) for s in subjects]);ax[1,1].set(title='Quality-pass coverage (no trial exclusion)',ylim=(0,1),xlabel='Participant');fig.tight_layout();fig.savefig(out/'feature-summary.png',dpi=140);plt.close(fig)
 fig,axes=plt.subplots(5,3,figsize=(13,15));
 for i,s in enumerate(subjects):
  for j,rep in enumerate(['time','bandpower','csp']):
   axis=axes[i,j]
   for r in f:
    if r['subject']==s and r.get('representation')==rep and r['method']=='neural':
     curve=np.array(r['curves']);line=axis.plot(curve[:,0],alpha=.6)[0];axis.plot(curve[:,1],ls='--',color=line.get_color(),label=str(r['seed']))
   axis.set(title=f'Participant {s}: {rep}',xlabel='Update',ylabel='Cross entropy');axis.legend(fontsize=7)
 fig.suptitle('All training curves: solid training, dashed validation');fig.tight_layout();fig.savefig(out/'all-curves.png',dpi=120);plt.close(fig)
 fig,axes=plt.subplots(1,5,figsize=(16,3))
 for axis,g in zip(axes,groups):
  matrix=np.mean([r['confusion'] for r in f if r['group']==g],axis=0);axis.imshow(matrix,cmap='Blues');axis.set(title=g,xlabel='Predicted class',ylabel='Known task label',xticks=[0,1],yticks=[0,1])
  for i in range(2):
   for j in range(2):axis.text(j,i,f'{matrix[i,j]:.1f}',ha='center',color='white' if matrix[i,j]>(matrix.max()+matrix.min())/2 else 'black')
 fig.suptitle('Mean trial counts per configuration (seeds are not independent people)');fig.tight_layout();fig.savefig(out/'confusion.png',dpi=130);plt.close(fig)
 fig,axes=plt.subplots(1,2,figsize=(15,5))
 for i,p in enumerate(result['feature']):
  axes[0].scatter(np.array(p['differences'])*100,[i]*len(p['differences']));axes[0].errorbar(p['mean']*100,i,xerr=[[100*(p['mean']-p['bootstrap95'][0])],[100*(p['bootstrap95'][1]-p['mean'])]],fmt='kx')
 axes[0].set(yticks=range(5),yticklabels=[' minus '.join(p) for p in comparisons],xlabel='Paired difference, percentage points');axes[0].axvline(0,color='gray')
 for method in methods:axes[1].plot(budgets,[mean([r for r in c if r['method']==method and r['budget']==b],'score')*100 for b in budgets],'-o',label=method)
 axes[1].set(xlabel='Calibration trials',ylabel='Balanced accuracy (%)',title='Eight participants; seeds averaged');axes[1].legend(loc='upper center',bbox_to_anchor=(.5,-.16),ncol=2);fig.tight_layout();fig.savefig(out/'paired-calibration.png',dpi=140);plt.close(fig)
 cs=sorted({r['subject'] for r in c});fig,axes=plt.subplots(4,2,figsize=(12,12))
 for s,axis in zip(cs,axes.flat):
  r=next(r for r in c if r['subject']==s and r['method']=='fine_tuned' and r['budget']==12 and r['seed']==101);axis.plot(r['labels'],'o-',label='Task label');axis.plot(np.argmax(r['probabilities'],axis=1),'x--',label='Prediction');axis.set(title=f'Participant {s}; quality pass {r["coverage"]:.0%}',xlabel='Evaluation trial',yticks=[0,1]);axis.legend(fontsize=7)
 fig.suptitle('Fine-tuned budget 12, seed 101: illustrative trial sequences');fig.tight_layout();fig.savefig(out/'calibration-sequences.png',dpi=120);plt.close(fig)
 def pair_table(values):return table(['Comparison','Budget','Mean difference (pp)','95% bootstrap interval (pp)','Participant differences (pp)'],[[' minus '.join(r['comparison']),r['budget'] or '—',f'{100*r["mean"]:.2f}',f'[{100*r["bootstrap95"][0]:.2f}, {100*r["bootstrap95"][1]:.2f}]',', '.join(f'{s}: {100*d:+.2f}' for s,d in zip(r['participants'],r['differences']))] for r in values])
 def img(name):return '<img alt="'+name.replace('-',' ')+'" src="'+name+'.png">'
 summary=[]
 for g in groups:
  rr=[r for r in f if r['group']==g];v=[r for r in verification['results'] if r['representation']+' '+r['method']==g];summary.append([g,f'{mean(rr,"score"):.2%}',len(rr),rr[0].get('parameters',193 if g=='bandpower lda' else 7),f'{np.median([r["seconds"] for r in rr]):.3f}' if all('seconds' in r for r in rr) else 'Not recorded',f'{1000*np.median([r["model_with_normalization"]["median_seconds"] for r in v]):.3f}',f'{1000*np.median([r["features_and_model"]["median_seconds"] for r in v]):.3f}',f'{1000*np.median([r["source_through_prediction"]["median_seconds"] for r in v]):.3f}'])
 teacher=json.loads((FEATURE/'teacher.json').read_text());qualified=[rep for rep in ['bandpower','csp'] if all(t['qualified'] for t in teacher if t['representation']==rep)]
 sections=['<h1>Microduck EEG research report</h1><p class="lead">Saved decoders reproduce their predictions. Established EEG features did not improve the tested neural networks on average. The evidence does not establish a confirmed winner.</p><p>These experiments classify left/right imagined-fist task labels from recorded human EEG. They do not establish continuous rest detection, live mind reading, neural mapping, or reliable human control of the duck. Synthetic neural-signal robot replay remains a separate working demonstration.</p><nav><a href="#features">Feature experiment</a> · <a href="#calibration">Calibration</a> · <a href="#verification">Verification and timing</a> · <a href="#evidence">Evidence downloads</a></nav>',
 '<h2 id="features">Exploratory feature experiment</h2><p>Five previously studied people (2–6): run 4 training, run 8 validation, run 12 evaluation. Same trials for every method; all quality flags are reported without exclusion. Neural seeds 101/202/303, 60 full-batch Adam updates, minimum validation loss checkpoint. All subjects 1–22 have been inspected previously.</p><ul><li>Time CNN: learns temporal patterns directly from filtered 64-channel electrode windows.</li><li>Band-power MLP: learns from 192 log-power features across 8–13, 13–20 and 20–30 Hz.</li><li>CSP MLP: learns from six trained spatial log-variance features.</li><li>LDA: a regularized statistical classifier using the same band-power or CSP features.</li></ul><p>Windows begin 1 second after annotation and last 2 seconds at 160 Hz; causal 8–30 Hz filtering and average reference. Features use volts, Welch 1-second segments and integrated V² before logarithm. Band edges reproduce the historical implementation exactly (upper edge excluded). CSP and normalization are fitted on run 4 only. Saved normalization is independently checked against that training run.</p>',table(['Decoder','Mean balanced accuracy','Configurations','Neural / LDA decision parameters','Historical train/save/check seconds','Model+normalization batch ms','Features+model batch ms','Source-through-prediction batch ms'],summary),'<p>Historical neural seconds include training, validation, checkpoint saving and reload checking. LDA parameter counts include decision coefficients and intercept only, excluding fitted scaler/CSP arrays. Statistical training times were not recorded and cannot be recovered without retraining. Seeds are not independent participants.</p>',img('feature-summary'),img('confusion'),'<h3>Paired comparisons</h3><p>Retrospective participant bootstrap: seeds averaged within each person, 10,000 resamples, random seed 712. Intervals are exploratory and unstable with five people, are not corrected for multiple comparisons, and do not validate population generalization.</p>',pair_table(result['feature']),img('paired-calibration'),'<details><summary>All training and validation curves</summary>'+img('all-curves')+'</details>',
 '<details><summary>Every participant and feature method</summary>'+table(['Participant','Decoder','Seed-mean BA','Individual seed BA','Quality pass','Trials'],[[s,g,f'{mean([r for r in f if r["subject"]==s and r["group"]==g],"score"):.2%}',', '.join(f'{r["seed"]}: {r["score"]:.2%}' for r in f if r['subject']==s and r['group']==g),f'{next(r["coverage"] for r in f if r["subject"]==s):.2%}',next(r['trials'] for r in f if r['subject']==s)] for s in subjects for g in groups])+'</details>',
 '<h3>Teacher decision</h3><p>Predefined qualification required validation balanced accuracy ≥80% and both class recalls ≥75% in every development participant. Qualified representations: '+html.escape(', '.join(qualified) if qualified else 'none')+'. No teacher qualified; distillation remains untested.</p>',
 '<h2 id="calibration">Personal calibration: separate experiment</h2><p>Eight previously inspected participants (15–22), calibration run 4 and evaluation run 12. Budgets 4/8/12 use nested first-per-class samples. Three seeds; pooled weights trained on 2–6, selected on 7–8. Fine-tuning used exactly 50 all-layer Adam updates at .001 with no target-person validation. This result concerns that specific update procedure, not every possible calibration method or generalization across days.</p><p>Shuffled-label runs were inadvertently also executed on final participants. They did not drive model selection and are not a formal permutation test. Development selection was limited to one update configuration.</p>',pair_table(result['calibration']),table(['Budget','Method','Mean BA','Left recall','Right recall','Quality coverage'],[[b,m,f'{mean([r for r in c if r["budget"]==b and r["method"]==m],"score"):.2%}',*[f'{np.mean([r["classification"][label]["recall"] for r in c if r["budget"]==b and r["method"]==m]):.2%}' for label in ['0','1']],f'{np.mean([r["coverage"] for r in c if r["budget"]==b and r["method"]==m]):.2%}'] for b in budgets for m in methods]),img('calibration-sequences'),'<details><summary>Calibration: every participant, budget and method</summary>'+table(['Participant','Budget','Method','Seed-mean BA','Left recall','Right recall'],[[person,b,m,f'{mean([r for r in c if r["subject"]==person and r["budget"]==b and r["method"]==m],"score"):.2%}',*[f'{np.mean([r["classification"][label]["recall"] for r in c if r["subject"]==person and r["budget"]==b and r["method"]==m]):.2%}' for label in ['0','1']]] for person in cs for b in budgets for m in methods])+'</details>',
 '<h2 id="verification">Independent artifact verification and offline timings</h2><p>'+str(len(verification['results']))+' configurations independently loaded from saved weights and transforms. Maximum probability difference '+str(max(r['max_probability_error'] for r in verification['results']))+'; tolerance 1e-6. Class predictions and scoring labels also matched. Hash-bound supplemental manifests document legacy provenance limits.</p><p>'+html.escape(verification['timing_note'])+'</p><p>CPU hardware: '+html.escape(str(verification['hardware']))+'. Torch threads 2; 3 warm-ups, 10 measured inference batches. Model timing includes normalization and tensor conversion; feature timing additionally includes feature extraction. Cold source processing uses an empty temporary cache once per person; warm cache uses 3 repetitions. Complete source-through-prediction timing uses 3 repetitions with an empty processed cache each time; operating-system file caches are uncontrolled. These are offline batch computation durations, not acquisition-to-command delay.</p>',table(['Participant','Cold source processing seconds','Warm cached median seconds'],[[s,f'{v["cold_source_preprocessing_seconds"]:.4f}',f'{v["warm_cache_load"]["median_seconds"]:.4f}'] for s,v in verification['sources'].items()]),
 '<h2>Research answer and next step</h2><p>Feature MLPs did not improve on the time CNN average. Band-power MLP underperformed its LDA counterpart; CSP MLP had a small exploratory advantage over CSP/LDA. Band-power LDA is the leading simple candidate for a future locked comparison, but its small advantage over the CNN does not establish superiority. No architecture expansion, new training, fresh participants, RL or live integration was performed for this completion task.</p>',
 '<h2 id="evidence">Evidence downloads</h2><p>Visual QA: report top section and calibration navigation/table layout were inspected in Edge on 2026-11-02; all five saved figure files were inspected directly. The earlier URL safety stop was not bypassed. Remaining disclosure/download interactions are unverified because later desktop capture failed twice with a window-crop/monitor error. Static resources and generation are tested.</p><p><a href="paired.json">Paired results</a> · <a href="classification-details.json">Every configuration: metrics, participant, probabilities, recall, coverage, curves</a> · <a href="verification.json">Verification and timing</a> · <a href="inference-contract.json">Supplemental artifact provenance</a></p><p>Rebuild with Open-EEG-Research-Report.cmd or python -m neuralduck.completion_report. Regeneration reads saved outputs only and requires no downloads or model training.</p>']
 (out/'verification.json').write_text(json.dumps(verification,indent=2));(out/'inference-contract.json').write_text((FEATURE/'inference-contract.json').read_text())
 style='body{font:16px system-ui;max-width:1200px;margin:32px auto;padding:0 20px;color:#182431;background:#f7f9fc}h1,h2{color:#123f61}img{max-width:100%;background:white;margin:15px 0}table{border-collapse:collapse;display:block;overflow:auto;background:white}th,td{padding:10px;border:1px solid #ccd5df;text-align:left;font-size:14px}nav,.lead{padding:18px;background:#e5eef7}details{margin:20px 0}a{color:#125e9a}'
 (out/'report.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Microduck EEG research report</title><style>'+style+'</style></head><body>'+''.join(sections)+'</body></html>',encoding='utf-8')
 print('Report:',out/'report.html')
